        emon.Port.Cells lb = emon.Port.newCells();
        StringBuilder t1 = emon.Testport.newText();
        StringBuilder t2 = emon.Testport.newText();
        // A single page has no recurrence to find: a line in the margin of a SIXTEEN-page document that is on one page only is
        // left in the flow.
        flPages(wd, ln, et, 16);
        flTop(wd, ln, et, emon.Testport.textBlob("Draft for review"), 5, 7200, 30000);
        emon.Testport.assertEq(flRun(wd, ln, et, 16, 0, 0, txt, md, lb, t1), 0, "once: well formed");
        emon.Testport.assertText(t1, "P:alpha beta.;P:alpha beta.;P:alpha beta.;P:alpha beta.;P:Draft for review;P:alpha beta.;P:alpha beta.;P:alpha beta.;P:alpha beta.;P:alpha beta.;P:alpha beta.;P:alpha beta.;P:alpha beta.;P:alpha beta.;P:alpha beta.;P:alpha beta.;P:alpha beta.;", "a line on one page of sixteen stays in the flow");
        // On two pages of sixteen it is still not enough (30 per cent of the pages are needed).
        flClear(wd, ln, et);
